"""Browser camera-only preview tests with generated bytes, no SSH or G1."""
import json
import re
import socket
import sys
import time
from pathlib import Path
from unittest import TestCase,main,mock
from urllib.request import Request,urlopen

sys.path.insert(0,str(Path(__file__).resolve().parents[2]/'tools'))
import G1_CAMERA_PREVIEW as p
import g1_camera_h264 as h


class PreviewTests(TestCase):
    def test_browser_preview_stop_owns_only_mock_camera(self):
        calls=[]
        def fake_camera(host,output_address,stop_event):
            calls.append(host)
            self.assertEqual(output_address[0],'127.0.0.1')
            self.assertNotEqual(output_address[1],5011)
            with socket.create_connection(output_address,timeout=2) as s:
                jpg=b'\xff\xd8generated-fixture\xff\xd9'
                s.sendall(p.HEADER.pack(b'G1CM',1,0,0,len(jpg))+jpg)
                stop_event.wait(5)
        def browser(url):
            with urlopen(url,timeout=2) as r:html=r.read().decode()
            self.assertIn('1920',html)
            for _ in range(30):
                with urlopen(url+'status',timeout=2) as r:status=json.load(r)
                if status['count']:break
                time.sleep(.01)
            self.assertEqual(status['count'],1)
            token=re.search(r"/stop/([A-Za-z0-9_-]+)",html)[1]
            with urlopen(Request(url+'stop/'+token,method='POST'),timeout=2) as r:
                self.assertEqual(r.status,200)
        with mock.patch.object(p,'run',side_effect=fake_camera),mock.patch.object(p.webbrowser,'open',side_effect=browser):
            self.assertEqual(p.serve('fixture',seconds=5),0)
        self.assertEqual(calls,['fixture'])

    def test_output_address_rejects_nonlocal_before_login(self):
        with mock.patch.object(h,'ensure_login') as login:
            with self.assertRaises(ValueError):h.run('fixture',output_address=('192.168.1.2',5011))
            login.assert_not_called()


if __name__=='__main__':main()
